-- =========================================================================
-- seed_geography_national.sql — ALL Lao provinces / districts / villages
-- =========================================================================
-- Source: tax_ets MySQL (apis.com.la) provinces/districts/villages tables,
-- extracted verbatim (province 18, districts 148, villages 8,828).
--
-- Official codes are the natural key, and the code prefixes nest:
--   province 13  ->  district 1301  ->  village 1301001
--
-- Idempotent (UPSERT on code) and NON-DESTRUCTIVE: it never truncates, so
-- existing parcels/zones keep their FKs. Run migration 003 first (it adds the
-- UNIQUE(villages.code) index this file upserts against); the guard below
-- makes a standalone run safe too.
--
-- Supersedes the geography section of seed_savannakhet.sql (which is now
-- zone-rates only). Apply by hand on the server.
-- =========================================================================

SET search_path = landfee;

-- Precondition: UNIQUE(villages.code) — self-healing, mirrors migration 003.
DO $$
DECLARE dup int;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE c.relname = 'villages_code_key' AND n.nspname = 'landfee'
  ) THEN
    SELECT count(*) INTO dup FROM (
      SELECT code FROM villages GROUP BY code HAVING count(*) > 1
    ) x;
    IF dup > 0 THEN
      RAISE EXCEPTION 'Cannot add UNIQUE(villages.code): % duplicate code(s).', dup;
    END IF;
    CREATE UNIQUE INDEX villages_code_key ON villages (code);
  END IF;
END $$;

-- Legacy Savannakhet province code -> official '13' (id preserved).
UPDATE provinces SET code = '13'
 WHERE code = 'SVK' AND NOT EXISTS (SELECT 1 FROM provinces WHERE code = '13');

